<?php require "vendor/autoload.php"; $app = require_once "bootstrap/app.php"; $kernel = $app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $request = Illuminate\Http\Request::create("/customer/profile", "POST", ["name" => "Customer Test", "phone" => "1234567890", "language" => "en", "timezone" => "UTC", "date_format" => "Y-m-d"]); $user = App\Models\User::where("role", "customer")->first(); if(!$user){$user = App\Models\User::first();} auth()->login($user); $controller = app(App\Http\Controllers\CustomerDashboardController::class); try { $response = $controller->updateProfile($request); dump(session()->get("errors") ? session()->get("errors")->messages() : null); dump(session()->get("success")); } catch (\Exception $e) { dump($e->getMessage()); }
